 review=B/'results/gf180_full64_input_edge_failure_diagnosis_v1.json';assert not review.exists();review.write_text(json.dumps(dict(diagnosis_completed=True,observed='The180s run reached first input edge but timed out;660s extension ended with timestep-too-small exactly1.99us at the beginning of the10ns candidate rise. Ngspice exit0 did not indicate completion; trace208rows stops1.99us, before any half/all state response. Error namesVMAX source branch but this alone does not prove a clamp defect.',hypothesis='An ideal0.8V/10ns candidate slew drives a stiff large hierarchical-PEX network. The independently qualified bare full64 reduction completed this fixture; attached frontend or different capacitance model introduces the failure.',one_focused_repair='Change only external candidate rise10ns to100ns, ending at the same2us/4us times; same native geometry, references, solver,6us and660s native wall bound. No artificial ideal internal ROOT or reduced capacitor set. This is an external fixture diagnostic, not proof of actual input drivers.',next_if_unsuccessful='Close joined transient branch for current milestone, preserve source/GDS/LEF and three native DC cases, record dynamic gap. No tolerance/startup/slew sweep.',sha256={p.relative_to(R).as_posix():sha(p) for p in [p,rp,log]}),indent=2)+'\n')
 s=p.read_text().replace('1.99u 1.2 2u 2.0','1.9u 1.2 2u 2.0').replace('3.99u 1.2 4u 2.0','3.9u 1.2 4u 2.0')
 s=s.replace('unchanged actual geometry, solver and three-level stimulus.','unchanged actual geometry, solver and three levels; one focused diagnostic slows only external candidate rises from10ns to100ns after an abort exactly at the first edge.')
 d=p.with_name('screen_gf180_full64_rms_frontend_hierarchical_transient_v3.py');assert not d.exists();d.write_text(s)
